package com.primehr.learningdevelopment.plan.api;
import com.primehr.learningdevelopment.plan.api.LdPlanDtos.*;import com.primehr.learningdevelopment.plan.application.LdPlanService;import com.primehr.security.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/primehr/v1/learning-development")
public class LdPlanController{
 private final LdPlanService service;private final LdPlanningPermissionGuard permission;private final AgencyScopeResolver agency;
 public LdPlanController(LdPlanService service,LdPlanningPermissionGuard permission,AgencyScopeResolver agency){this.service=service;this.permission=permission;this.agency=agency;}
 private String agency(Authentication a){return agency.resolveAgencyId(a);}private static String actor(Authentication a){if(a==null||a.getName()==null||a.getName().isBlank())throw new org.springframework.security.access.AccessDeniedException("Authenticated employee identity is required");return a.getName();}
 @GetMapping("/needs")public List<NeedResponse>needs(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam(required=false)String employeeNo){return service.needs(agency(a),actor(a),permission.require(LdPlanningPermissionGuard.NEEDS,PrimeHrAction.ACCESS,t),employeeNo);}
 @PostMapping("/needs")@ResponseStatus(HttpStatus.CREATED)public NeedResponse createNeed(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid@RequestBody NeedInput in){return service.createNeed(agency(a),in,t,actor(a),permission.require(LdPlanningPermissionGuard.NEEDS,PrimeHrAction.ADD,t),c);}
 @PutMapping("/needs/{id}")public NeedResponse updateNeed(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody NeedInput in){return service.updateNeed(agency(a),id,in,actor(a),permission.require(LdPlanningPermissionGuard.NEEDS,PrimeHrAction.EDIT,t),c);}
 @PostMapping("/needs/{id}/cancel")public NeedResponse cancelNeed(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IdpTransition in){return service.cancelNeed(agency(a),id,in.recordVersion(),actor(a),permission.require(LdPlanningPermissionGuard.NEEDS,PrimeHrAction.ARCHIVE,t),c);}
 @PostMapping("/referrals/{id}/disposition")public ReferralDispositionResponse disposition(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody ReferralDispositionInput in){return service.disposition(agency(a),id,in,actor(a),permission.require(LdPlanningPermissionGuard.NEEDS,PrimeHrAction.APPROVE,t),c);}
 @GetMapping("/individual-plans")public List<IdpResponse>plans(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam(required=false)String employeeNo){return service.plans(agency(a),actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.ACCESS,t),employeeNo);}
 @GetMapping("/individual-plans/{id}")public IdpResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){return service.get(agency(a),id,actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.ACCESS,t));}
 @PostMapping("/individual-plans")@ResponseStatus(HttpStatus.CREATED)public IdpResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid@RequestBody IdpCreate in){return service.create(agency(a),in,t,actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.ADD,t),c);}
 @PutMapping("/individual-plans/{id}")public IdpResponse update(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IdpGoalUpdate in){return service.updateGoal(agency(a),id,in,actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.EDIT,t),c);}
 @PostMapping("/individual-plans/{id}/items")public IdpResponse addItem(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IdpItemInput in){return service.addItem(agency(a),id,in,actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.EDIT,t),c);}
 @PutMapping("/individual-plans/{id}/items/{itemId}")public IdpResponse updateItem(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String itemId,@Valid@RequestBody IdpItemUpdate in){return service.updateItem(agency(a),id,itemId,in,actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.EDIT,t),c);}
 @DeleteMapping("/individual-plans/{id}/items/{itemId}")public IdpResponse removeItem(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String itemId,@Valid@RequestBody IdpTransition in){return service.removeItem(agency(a),id,itemId,in,actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.EDIT,t),c);}
 @PostMapping("/individual-plans/{id}/submit")public IdpResponse submit(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IdpTransition in){return service.submit(agency(a),id,in,t,actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.SUBMIT,t),c);}
 @PostMapping("/individual-plans/{id}/recommend")public IdpResponse recommend(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IdpTransition in){permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.APPROVE,t);return service.recommend(agency(a),id,in,t,actor(a),c);}
 @PostMapping("/individual-plans/{id}/return")public IdpResponse returned(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IdpTransition in){permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.APPROVE,t);return service.returnForChanges(agency(a),id,in,t,actor(a),c);}
 @PostMapping("/individual-plans/{id}/approve")public IdpResponse approve(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IdpTransition in){permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.FINALIZE,t);return service.approve(agency(a),id,in,t,actor(a),c);}
 @PostMapping("/individual-plans/{id}/cancel")public IdpResponse cancel(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IdpTransition in){return service.cancel(agency(a),id,in,actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.ARCHIVE,t),c);}
 @PostMapping("/individual-plans/{id}/amendments")@ResponseStatus(HttpStatus.CREATED)public IdpResponse amend(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid@RequestBody IdpTransition in){return service.amend(agency(a),id,in,actor(a),permission.require(LdPlanningPermissionGuard.IDP,PrimeHrAction.FINALIZE,t),c);}
}
